                            break
                    if swapped:
                        break

    # Final cleanup: remove empty routes and ensure all customers are present
    routes = [r for r in routes if r]

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = []
    for c in customers:
        if seen.get(c, 0) == 0:
            missing.append(c)

    if missing:
        for c in missing:
            placed = False
            dc = demand.get(c, 1)
            for r in routes:
                if route_load(r) + dc <= capacity:
                    best_pos = 0
                    best_inc = None
                    for pos in range(len(r) + 1):
                        prev = depot if pos == 0 else r[pos - 1]
                        nxt = depot if pos == len(r) else r[pos]
                        inc = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                        if best_inc is None or inc < best_inc:
                            best_inc = inc
                            best_pos = pos
                    r.insert(best_pos, c)
                    placed = True
                    break
            if not placed:
                routes.append([c])

    return routes
